var types = require('./types');
var INTS = function INTS() {
  return [{
    type: types.RANGE,
    from: 48,
    to: 57
  }];
};
var WORDS = function WORDS() {
  return [{
    type: types.CHAR,
    value: 95
  }, {
    type: types.RANGE,
    from: 97,
    to: 122
  }, {
    type: types.RANGE,
    from: 65,
    to: 90
  }].concat(INTS());
};
var WHITESPACE = function WHITESPACE() {
  return [{
    type: types.CHAR,
    value: 9
  }, {
    type: types.CHAR,
    value: 10
  }, {
    type: types.CHAR,
    value: 11
  }, {
    type: types.CHAR,
    value: 12
  }, {
    type: types.CHAR,
    value: 13
  }, {
    type: types.CHAR,
    value: 32
  }, {
    type: types.CHAR,
    value: 160
  }, {
    type: types.CHAR,
    value: 5760
  }, {
    type: types.RANGE,
    from: 8192,
    to: 8202
  }, {
    type: types.CHAR,
    value: 8232
  }, {
    type: types.CHAR,
    value: 8233
  }, {
    type: types.CHAR,
    value: 8239
  }, {
    type: types.CHAR,
    value: 8287
  }, {
    type: types.CHAR,
    value: 12288
  }, {
    type: types.CHAR,
    value: 65279
  }];
};
var NOTANYCHAR = function NOTANYCHAR() {
  return [{
    type: types.CHAR,
    value: 10
  }, {
    type: types.CHAR,
    value: 13
  }, {
    type: types.CHAR,
    value: 8232
  }, {
    type: types.CHAR,
    value: 8233
  }];
};

// Predefined class objects.
exports.words = function () {
  return {
    type: types.SET,
    set: WORDS(),
    not: false
  };
};
exports.notWords = function () {
  return {
    type: types.SET,
    set: WORDS(),
    not: true
  };
};
exports.ints = function () {
  return {
    type: types.SET,
    set: INTS(),
    not: false
  };
};
exports.notInts = function () {
  return {
    type: types.SET,
    set: INTS(),
    not: true
  };
};
exports.whitespace = function () {
  return {
    type: types.SET,
    set: WHITESPACE(),
    not: false
  };
};
exports.notWhitespace = function () {
  return {
    type: types.SET,
    set: WHITESPACE(),
    not: true
  };
};
exports.anyChar = function () {
  return {
    type: types.SET,
    set: NOTANYCHAR(),
    not: true
  };
};